export async function exchangeLinkedInCode(code: string) {
  const res = await fetch("https://www.linkedin.com/oauth/v2/accessToken", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "authorization_code",
      code,
      client_id: process.env.LINKEDIN_CLIENT_ID!,
      client_secret: process.env.LINKEDIN_CLIENT_SECRET!,
      redirect_uri: process.env.LINKEDIN_REDIRECT_URI!,
    }),
  });
  const t = await res.json();
  if (!res.ok) throw new Error(`${t.error}: ${t.error_description}`);
  const now = Date.now();
  return {
    accessToken: t.access_token as string,
    expiresAt: new Date(now + t.expires_in * 1000),
    scope: t.scope as string,
    // Present only if LinkedIn enabled programmatic refresh tokens for this app
    refreshToken: (t.refresh_token as string | undefined) ?? null,
    refreshExpiresAt: t.refresh_token_expires_in ? new Date(now + t.refresh_token_expires_in * 1000) : null,
  };
}
